        "API" -> "Legacy CRM" "Synchronises customer data" "REST"
    }

    views {
        systemContext "WebShop" "WebShopContext" {
            "A system context diagram for the WebShop."
            include *
            autoLayout
        }

        container "WebShop" "WebShopContainers" {
            "A container diagram for the WebShop."
            include *
            autoLayout
        }

        theme default
    }

    !docs
}`;

const result = await tools.structurizr.validate({ dsl });
return result;

